worker_runtime() {
  run systemctl is-active kubelet containerd
  if command -v crictl >/dev/null && command -v python3 >/dev/null; then run cri_health; else skip 'phase04.message.m_159a3096b7c5'; fi
  optional crictl --runtime-endpoint unix:///run/containerd/containerd.sock ps -a
  optional crictl --runtime-endpoint unix:///run/containerd/containerd.sock images
  optional ctr -n k8s.io containers list
}
cri_health() {
  crictl --runtime-endpoint unix:///run/containerd/containerd.sock info | python3 -c '
import json,sys
try: conditions=json.load(sys.stdin)["status"]["conditions"]
except (ValueError,KeyError): sys.exit(sys.argv[1])
states={c["type"]:c["status"] for c in conditions}
print(sys.argv[2],states)
sys.exit(0 if states.get("RuntimeReady") is True and states.get("NetworkReady") is True else 1)' "$(t 'phase04.message.m_c2715b66c074')" "$(t 'phase04.message.m_bec0fe5646f4')"
}
worker_cni() {
  optional ip -br link
  optional ip route
  optional ls -l /etc/cni/net.d
  note 'phase04.message.m_c419a30c0474'
}
worker_api() {
  endpoint_input || return
  optional python3 -c 'import socket,sys,urllib.parse; u=urllib.parse.urlparse(sys.argv[1]); s=socket.create_connection((u.hostname,u.port or 6443),timeout=5); print(sys.argv[2],u.netloc); s.close()' "$ENDPOINT" "$(t 'phase04.message.m_6f825383e37e')"
  note 'phase04.message.m_71c32f69a24b'
}
summary() {
  local_host; identity; disks
  case "$ROLE" in
    cp) run systemctl is-active kubelet containerd; if [ "$API_AVAILABLE" -eq 1 ]; then nodes; pods; api_health; else skip 'phase04.message.m_3a9a549f0dab'; fi;;
    worker) run systemctl is-active kubelet containerd;;
    lb) run systemctl is-active haproxy keepalived; optional ss -lntp;;
  esac
  note 'phase04.message.m_dad994f6b941'
}
add_menu() { LABELS+=("$(t "$1")"); ACTIONS+=("$2"); }
build_menu() {
  LABELS=() ACTIONS=()
  add_menu 'phase04.menu.item.774305b38b8f' local_host
  add_menu 'phase04.menu.item.53bd34dc3ca6' identity
  add_menu 'phase04.menu.item.0f16a58134c9' ssh_mesh
  add_menu 'phase04.menu.item.7b0136268bd6' services
