    add_menu 'phase04.menu.item.263a290cc233' nodes
    add_menu 'phase04.menu.item.27de3f2a9ee7' pods
    add_menu 'phase04.menu.item.6e5523df7863' api_health
    add_menu 'phase04.menu.item.d12738fd1258' system_health
    add_menu 'phase04.menu.item.3997b76b9ae1' dns_status
