  if [ "$ROLE" = lb ]; then
    add_menu 'phase04.menu.item.59bfcc763c0b' lb_health
    [ ! -r /etc/haproxy/haproxy.cfg ] || add_menu 'phase04.menu.item.f0907d3f55cb' lb_backends
    command -v curl >/dev/null && add_menu 'phase04.menu.item.b3525d36b0ce' lb_vip
