  fi
  add_menu 'phase04.menu.item.155837d4cf50' summary
}
while true; do
  build_menu
  printf '\n=== Atlas KubeKit %s | %s | %s (%s) ===\n' "$ATLAS_KUBEKIT_VERSION" "$(t 'phase04.message.m_9bc879af3781')" "$SELF" "$ROLE"
  [ "$ROLE" != unknown ] || warn 'phase04.message.m_934ff702cc3f'
  if [ "$ROLE" = cp ] && [ "$API_AVAILABLE" -eq 0 ]; then warn 'phase04.message.m_3c191dcf41d9'; fi
  for i in "${!LABELS[@]}"; do printf '%2d) %s\n' "$((i + 1))" "${LABELS[$i]}"; done
  printf ' L) %s\n 0) %s\n' "$(t 'phase04.message.m_e3edac1ee6f3')" "$(t 'phase04.message.m_f83b6fe3aebf')"
  choice="$(ask 'phase04.message.m_065c47dfb142' 0)" || exit 0
  case "$choice" in 0) exit 0;; L|l) choose_language || exit 0; continue;; esac
  found=0
  for i in "${!LABELS[@]}"; do
    if [ "$choice" = "$((i + 1))" ]; then
      found=1; ERRORS=0; SKIPS=0; DISCOVERED=0; RESOURCES=''
      "${ACTIONS[$i]}"
      ui_format 'phase04.message.m_ebdb15ba4b32' "$ERRORS" "$SKIPS"
      read -r -p "$(t 'phase04.message.m_a6873f9f44af')" _ || exit 0
      break
    fi
  done
  [ "$found" -eq 1 ] || warn 'phase04.message.m_132d7bdc11bd'
done
